    const s = G.save
    if (!s.flags.towerDone) {
      await Dialog.show({ speaker: 'Gardien de la Ligue', text: 'Le Maître ne reçoit que les dresseurs qui ont triomphé des huit arènes de l’Île des Épreuves.' })
