import {
  BADGES, ITEMS, LOCATIONS, LOCATION_ORDER, ONLINE_RANKS, SPECIES, TYPE_COLORS, TYPE_ICONS, AI_NAMES
} from './data.js'

input.newString:
import {
  BADGES, ITEMS, LOCATIONS, LOCATION_ORDER, ONLINE_RANKS, SPECIES, TYPE_COLORS, TYPE_ICONS, AI_NAMES, MOVES
} from './data.js'

input.content:
/* Pokémon Templier — visual system */
:root {
  --ink: #080d18;
  --night: #0b1120;
  --night2: #111a2c;
  --night3: #17223a;
  --panel: rgba(14, 21, 38, .88);
  --panel2: rgba(20, 30, 52, .92);
  --gold: #f0c96b;
  --gold2: #c9a45a;
  --gold3: #8a5b2e;
  --sand: #e8d5a8;
  --parchment: #f2e3c2;
  --muted: #9aa7bd;
  --text: #edf1f8;
  --red: #e4572e;
  --teal: #7de0d8;
  --green: #55b85f;
  --blue: #4b8ef7;
  --line: rgba(240, 201, 107, .28);
  --line-soft: rgba(240, 201, 107, .12);
  --shadow: 0 24px 70px rgba(0, 0, 0, .55);
  --serif: Georgia, "Times New Roman", serif;
  --sans: "Trebuchet MS", "Segoe UI", system-ui, -apple-system, sans-serif;
}

* { box-sizing: border-box; }
html, body { height: 100%; }
body {
  margin: 0;
  background: var(--night);
  color: var(--text);
  font-family: var(--sans);
  overflow: hidden;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}
button, input, select { font: inherit; color: inherit; }
button { cursor: pointer; }
button:disabled { cursor: not-allowed; opacity: .45; }
h1, h2, h3, h4, p { margin: 0; }
::selection { background: rgba(240, 201, 107, .3); }

/* scrollbars */
* { scrollbar-width: thin; scrollbar-color: rgba(240, 201, 107, .35) transparent; }
*::-webkit-scrollbar { width: 8px; height: 8px; }
*::-webkit-scrollbar-thumb { background: rgba(240, 201, 107, .3); border-radius: 8px; }
*::-webkit-scrollbar-track { background: transparent; }

.eyebrow {
  display: inline-block;
  font-size: 10px;
  letter-spacing: 2.2px;
  text-transform: uppercase;
  color: var(--gold);
  font-weight: 700;
}
.muted { color: var(--muted); }
.small { font-size: 12px; }
.panel {
  background: linear-gradient(160deg, rgba(21, 31, 54, .96), rgba(10, 16, 30, .97));
  border: 1px solid var(--line);
  border-radius: 18px;
  box-shadow: var(--shadow), inset 0 1px 0 rgba(255, 255, 255, .05);
  position: relative;
}
.panel::before, .panel::after {
  content: "";
  position: absolute;
  width: 26px; height: 26px;
  border: 1px solid var(--gold);
  opacity: .55;
  pointer-events: none;
}
.panel::before { top: 8px; left: 8px; border-right: 0; border-bottom: 0; border-radius: 8px 0 0 0; }
.panel::after { bottom: 8px; right: 8px; border-left: 0; border-top: 0; border-radius: 0 0 8px 0; }

/* buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 42px;
  padding: 10px 18px;
  border-radius: 11px;
  border: 1px solid rgba(240, 201, 107, .35);
  background: linear-gradient(180deg, rgba(42, 56, 86, .85), rgba(18, 27, 46, .92));
  color: var(--parchment);
  font-weight: 700;
  letter-spacing: .3px;
  transition: transform .16s ease, border-color .16s ease, background .16s ease, box-shadow .16s ease;
  box-shadow: 0 8px 22px rgba(0, 0, 0, .28), inset 0 1px 0 rgba(255, 255, 255, .06);
}
.btn:hover:not(:disabled) { transform: translateY(-2px); border-color: rgba(240, 201, 107, .75); box-shadow: 0 12px 28px rgba(0, 0, 0, .35), 0 0 24px rgba(240, 201, 107, .1); }
.btn:active:not(:disabled) { transform: translateY(0) scale(.99); }
.btn.gold {
  background: linear-gradient(180deg, #f7dd9a, #d9a441 55%, #a9742b);
  border-color: #ffe6a8;
  color: #2b1a08;
  text-shadow: 0 1px 0 rgba(255, 255, 255, .3);
}
.btn.gold:hover:not(:disabled) { box-shadow: 0 12px 34px rgba(240, 201, 107, .25), 0 0 0 1px rgba(255, 230, 168, .4); }
.btn.ghost { background: rgba(10, 16, 30, .5); border-color: rgba(240, 201, 107, .22); }
.btn.danger { background: linear-gradient(180deg, #8a2e2e, #521a1a); border-color: rgba(228, 87, 46, .5); }
.btn.big { min-height: 54px; padding: 14px 28px; font-size: 16px; }
.btn.small { min-height: 30px; padding: 5px 10px; font-size: 11px; border-radius: 8px; }
.btn.full { width: 100%; }
.icon-btn {
  width: 40px; height: 40px; border-radius: 50%;
  border: 1px solid var(--line); background: rgba(10, 16, 30, .6); color: var(--parchment);
}
.mini-btn {
  border: 1px solid rgba(240, 201, 107, .28);
  background: rgba(24, 35, 58, .9);
  color: var(--parchment);
  border-radius: 7px;
  padding: 5px 10px;
  font-size: 11px;
  font-weight: 700;
  white-space: nowrap;
}
.mini-btn:hover:not(:disabled) { border-color: var(--gold); background: rgba(42, 58, 88, .95); }
.mini-btn.gold { background: linear-gradient(180deg, #f0c96b, #c9a45a); color: #2b1a08; border-color: #ffe6a8; }
.mini-btn.danger { background: rgba(120, 30, 30, .8); }

/* boot */
.boot {
  position: fixed; inset: 0; z-index: 200;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: 10px; background: radial-gradient(circle at 50% 40%, #17223a, #070b14 70%);
  transition: opacity .6s ease, visibility .6s;
}
.boot.hide { opacity: 0; visibility: hidden; }
.boot-mark { font-size: 58px; color: var(--gold); text-shadow: 0 0 40px rgba(240, 201, 107, .4); animation: pulse 2s infinite; }
.boot-title { font-family: var(--serif); font-size: 24px; letter-spacing: 8px; color: var(--parchment); }
.boot-sub { font-size: 12px; letter-spacing: 3px; color: var(--muted); text-transform: uppercase; }
.boot-bar { width: 180px; height: 3px; background: rgba(240, 201, 107, .15); border-radius: 3px; overflow: hidden; margin-top: 10px; }
.boot-bar span { display: block; height: 100%; width: 40%; background: var(--gold); border-radius: 3px; animation: bootbar 1.2s infinite ease-in-out; }
@keyframes bootbar { 0% { transform: translateX(-100%); } 100% { transform: translateX(350%); } }
@keyframes pulse { 0%,100% { transform: scale(1); opacity: .85; } 50% { transform: scale(1.06); opacity: 1; } }

/* screens */
.screen { position: fixed; inset: 0; display: none; overflow: hidden; }
.screen.active { display: flex; }

/* ------------------------------------------------------------------ */
/* TITLE */
/* ------------------------------------------------------------------ */
#screen-title { align-items: center; justify-content: center; background: #0a1024; }
.title-scene { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.title-particles { position: absolute; inset: 0; width: 100%; height: 100%; pointer-events: none; opacity: .8; }
.title-content {
  position: relative; z-index: 2; text-align: center; padding: 32px 22px;
  max-width: 920px; width: 100%;
  animation: rise .9s cubic-bezier(.2,.8,.2,1) both;
}
@keyframes rise { from { opacity: 0; transform: translateY(18px); } to { opacity: 1; transform: translateY(0); } }
.title-kicker {
  display: inline-flex; align-items: center; gap: 12px;
  font-size: 11px; letter-spacing: 3px; text-transform: uppercase; color: #f5d79b;
  text-shadow: 0 2px 14px rgba(0,0,0,.7);
}
.title-kicker span { width: 38px; height: 1px; background: linear-gradient(90deg, transparent, #f0c96b); }
.title-kicker span:last-child { background: linear-gradient(90deg, #f0c96b, transparent); }
.title-logo { margin: 12px 0 4px; line-height: .9; position: relative; }
.logo-pokemon {
  display: block; font-family: var(--serif); font-size: clamp(18px, 3.2vw, 34px);
  letter-spacing: clamp(5px, 1.4vw, 14px); color: #f5e6c2;
  text-shadow: 0 2px 0 #6b4a18, 0 5px 24px rgba(0,0,0,.65);
}
.logo-templier {
  display: block; font-family: var(--serif); font-weight: 700;
  font-size: clamp(54px, 11vw, 118px); letter-spacing: clamp(2px, 1vw, 12px);
  background: linear-gradient(180deg, #fff6d0 0%, #f0c96b 34%, #c9a45a 62%, #8a5b2e 100%);
  -webkit-background-clip: text; background-clip: text; color: transparent;
  filter: drop-shadow(0 4px 0 #4a2e10) drop-shadow(0 12px 30px rgba(0,0,0,.65));
}
.logo-underline {
  display: block; width: min(440px, 70%); height: 2px; margin: 10px auto 0;
  background: linear-gradient(90deg, transparent, #f0c96b, transparent);
  box-shadow: 0 0 20px rgba(240,201,107,.55);
}
.title-sub { margin: 14px 0 28px; color: #f2e3c2; font-size: clamp(12px, 1.6vw, 16px); letter-spacing: 1px; text-shadow: 0 2px 12px rgba(0,0,0,.8); }
.title-actions { display: flex; flex-direction: column; align-items: center; gap: 10px; }
.title-actions .btn { width: min(360px, 84vw); }
.maint-pill {
  font-size: 9px; text-transform: uppercase; letter-spacing: 1px;
  padding: 3px 7px; border-radius: 20px; background: rgba(228, 87, 46, .2);
  border: 1px solid rgba(228, 87, 46, .55); color: #ffb08a;
}
.title-save { margin-top: 14px; font-size: 11px; color: #c9d3e4; text-shadow: 0 2px 10px #000; }
.title-footer {
  position: absolute; left: 0; right: 0; bottom: 0; z-index: 3;
  display: flex; align-items: center; justify-content: space-between; gap: 14px;
  padding: 14px 22px calc(14px + env(safe-area-inset-bottom));
  font-size: 10px; letter-spacing: .5px; color: rgba(242, 227, 194, .6);
  background: linear-gradient(0deg, rgba(5,8,16,.75), transparent);
}
.title-tip { opacity: .8; }
.title-footer .icon-btn { width: 34px; height: 34px; }

/* ------------------------------------------------------------------ */
/* INTRO */
/* ------------------------------------------------------------------ */
#screen-intro { background: #0a1024; align-items: center; justify-content: center; }
.intro-bg {
  position: absolute; inset: 0;
  background:
    radial-gradient(circle at 22% 32%, rgba(240, 201, 107, .22), transparent 42%),
    radial-gradient(circle at 82% 70%, rgba(228, 87, 46, .16), transparent 45%),
    linear-gradient(150deg, #101a30, #0a1020 55%, #1a1420);
}
.intro-bg::before {
  content: ""; position: absolute; inset: 0;
  background-image: radial-gradient(rgba(240,201,107,.22) 1px, transparent 1px);
  background-size: 46px 46px; opacity: .16;
  mask-image: radial-gradient(circle at 50% 50%, #000, transparent 75%);
}
.intro-layout {
  position: relative; z-index: 2; width: min(1240px, 94vw); height: min(820px, 88dvh);
  display: grid; grid-template-columns: .88fr 1.12fr; gap: 26px; align-items: center;
}
.intro-art { height: 100%; display: flex; align-items: flex-end; justify-content: center; }
.professor-art { width: min(100%, 480px); height: 100%; filter: drop-shadow(0 30px 40px rgba(0,0,0,.55)); animation: profIn 1.1s cubic-bezier(.2,.8,.2,1) both; }
@keyframes profIn { from { opacity: 0; transform: translateY(24px) scale(.97); } to { opacity: 1; transform: none; } }
.intro-panel { height: 100%; max-height: 100%; display: flex; flex-direction: column; padding: 26px 28px; overflow: hidden; }
.intro-top { display: flex; align-items: center; justify-content: space-between; }
.intro-step { font-family: var(--serif); font-size: 26px; color: rgba(240, 201, 107, .55); }
.intro-speaker { display: flex; align-items: baseline; gap: 10px; margin: 16px 0 10px; flex-wrap: wrap; }
.intro-speaker strong { font-family: var(--serif); font-size: 22px; color: var(--parchment); }
.intro-speaker small { color: var(--muted); font-size: 11px; letter-spacing: 1px; }
.speaker-dot { width: 9px; height: 9px; border-radius: 50%; background: var(--gold); box-shadow: 0 0 14px var(--gold); }
.intro-text {
  font-size: 15.5px; line-height: 1.65; color: #dfe6f2; min-height: 150px;
  overflow-y: auto; padding-right: 6px; flex: 1 1 auto;
}
.intro-text p { margin-bottom: 10px; }
.intro-text .hl { color: var(--gold); font-weight: 700; }
.intro-text .lore-quote {
  border-left: 2px solid var(--gold2); padding: 8px 0 8px 14px; color: #f5e6c2;
  font-family: var(--serif); font-size: 17px; font-style: italic; margin: 12px 0;
}
.intro-form { margin-top: 12px; }
.intro-actions { display: flex; gap: 10px; justify-content: flex-end; margin-top: 16px; flex-wrap: wrap; }
.intro-actions .btn { min-width: 150px; }
.intro-skip {
  position: absolute; right: 22px; bottom: 18px; z-index: 3;
  border: 0; background: transparent; color: rgba(242, 227, 194, .55);
  font-size: 11px; letter-spacing: .6px;
}
.intro-skip:hover { color: var(--gold); }

.form-grid { display: grid; gap: 14px; }
.form-row { display: grid; gap: 6px; }
.form-row label { font-size: 11px; text-transform: uppercase; letter-spacing: 1.6px; color: var(--gold); font-weight: 700; }
.form-row input {
  width: 100%; padding: 12px 14px; border-radius: 10px;
  border: 1px solid rgba(240, 201, 107, .28); background: rgba(8, 13, 24, .7);
  color: var(--parchment); outline: none; font-size: 15px;
}
.form-row input:focus { border-color: var(--gold); box-shadow: 0 0 0 3px rgba(240, 201, 107, .12); }
.form-row small { color: var(--muted); font-size: 11px; }
.gender-row { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.gender-card {
  display: flex; align-items: center; gap: 12px; padding: 12px;
  border: 1px solid rgba(240, 201, 107, .2); border-radius: 12px;
  background: rgba(10, 16, 30, .55); text-align: left;
}
.gender-card .g-ico { font-size: 26px; }
.gender-card strong { display: block; font-size: 14px; }
.gender-card small { color: var(--muted); font-size: 11px; }
.gender-card.active { border-color: var(--gold); background: rgba(240, 201, 107, .1); box-shadow: 0 0 0 3px rgba(240, 201, 107, .08); }
.starter-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; }
.starter-card {
  position: relative; padding: 10px; border-radius: 14px; text-align: center;
  border: 1px solid rgba(240, 201, 107, .18); background: rgba(10, 16, 30, .55);
  transition: .16s ease;
}
.starter-card:hover { transform: translateY(-2px); border-color: rgba(240, 201, 107, .5); }
.starter-card.active { border-color: var(--gold); background: rgba(240, 201, 107, .09); box-shadow: 0 0 0 3px rgba(240, 201, 107, .08); }
.starter-art { display: flex; justify-content: center; }
.starter-card strong { display: block; font-family: var(--serif); font-size: 16px; margin-top: 2px; }
.starter-card .type-row { justify-content: center; margin: 5px 0; }
.starter-card small { display: block; color: var(--muted); font-size: 10.5px; line-height: 1.35; min-height: 42px; }
.starter-tag { font-size: 10px; color: var(--gold); letter-spacing: .4px; }
.intro-summary { display: grid; gap: 10px; }
.summary-card { display: flex; gap: 14px; align-items: center; padding: 12px; border: 1px solid var(--line-soft); border-radius: 12px; background: rgba(10,16,30,.45); }
.summary-card .s-icon { font-size: 30px; }
.summary-card strong { display: block; font-family: var(--serif); font-size: 18px; }
.summary-card small { color: var(--muted); }

/* ------------------------------------------------------------------ */
/* HUD */
/* ------------------------------------------------------------------ */
#screen-game { flex-direction: column; height: 100dvh; background: #0a1024; }
#hud {
  position: relative; z-index: 30; flex: 0 0 auto;
  display: flex; align-items: center; gap: 14px;
  padding: 8px 16px calc(8px + env(safe-area-inset-top));
  background: linear-gradient(180deg, rgba(9, 14, 26, .98), rgba(12, 19, 34, .9));
  border-bottom: 1px solid rgba(240, 201, 107, .22);
  box-shadow: 0 8px 30px rgba(0,0,0,.35);
}
.hud-left { display: flex; align-items: center; gap: 14px; min-width: 0; }
.hud-location { min-width: 0; }
.hud-location h2 { font-family: var(--serif); font-size: 18px; line-height: 1.05; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.hud-location small { color: var(--muted); font-size: 10px; letter-spacing: .5px; white-space: nowrap; }
.hud-location .eyebrow { font-size: 8px; }
.hud-badges { display: flex; gap: 3px; align-items: center; }
.hud-objective {
  flex: 1 1 auto; text-align: center; color: #c9d3e4; font-size: 11px;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis; padding: 0 8px;
}
.hud-right { display: flex; align-items: center; gap: 4px; }
.hud-btn {
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 1px;
  min-width: 48px; height: 42px; padding: 2px 5px;
  border: 1px solid transparent; border-radius: 9px; background: transparent;
  color: #c9d3e4; transition: .15s ease;
}
.hud-btn span { font-size: 17px; line-height: 1; }
.hud-btn small { font-size: 8px; letter-spacing: .3px; color: var(--muted); }
.hud-btn:hover { background: rgba(240, 201, 107, .08); border-color: rgba(240, 201, 107, .22); color: var(--parchment); }
.hud-btn:hover small { color: var(--gold); }

#world-wrap { position: relative; flex: 1 1 auto; min-height: 0; overflow: hidden; background: #121a2a; }
#world { position: absolute; inset: 0; width: 100%; height: 100%; display: block; touch-action: none; }
.location-banner {
  position: absolute; top: 24px; left: 50%; transform: translate(-50%, -12px);
  z-index: 6; text-align: center; pointer-events: none; opacity: 0;
  transition: opacity .5s ease, transform .5s ease;
  text-shadow: 0 3px 18px rgba(0,0,0,.85);
}
.location-banner.show { opacity: 1; transform: translate(-50%, 0); }
.location-banner .lb-region { display: block; font-size: 9px; letter-spacing: 4px; color: var(--gold); text-transform: uppercase; }
.location-banner h2 { font-family: var(--serif); font-size: clamp(26px, 4vw, 46px); color: #fff3c4; letter-spacing: 2px; }
.location-banner p { font-size: 12px; color: #e8d5a8; letter-spacing: 1px; }
.world-prompt {
  position: absolute; left: 50%; bottom: 118px; transform: translate(-50%, 8px);
  z-index: 7; display: flex; align-items: center; gap: 9px;
  padding: 8px 16px 8px 8px; border-radius: 30px;
  background: rgba(8, 13, 24, .88); border: 1px solid rgba(240, 201, 107, .5);
  box-shadow: 0 12px 30px rgba(0,0,0,.45), 0 0 24px rgba(240,201,107,.1);
  opacity: 0; pointer-events: none; transition: .18s ease; white-space: nowrap;
}
.world-prompt.show { opacity: 1; transform: translate(-50%, 0); }
.world-prompt .key {
  display: inline-flex; align-items: center; justify-content: center;
  width: 26px; height: 26px; border-radius: 50%;
  background: linear-gradient(180deg, #f7dd9a, #c9a45a); color: #2b1a08;
  font-weight: 900; font-size: 12px; box-shadow: 0 0 12px rgba(240,201,107,.4);
}
.world-prompt span:last-child { font-size: 12px; color: var(--parchment); }
.world-controls-hint {
  position: absolute; left: 14px; bottom: 12px; z-index: 5;
  font-size: 9.5px; letter-spacing: .4px; color: rgba(242, 227, 194, .55);
  background: rgba(8,13,24,.55); padding: 5px 9px; border-radius: 7px;
  border: 1px solid rgba(240,201,107,.12); pointer-events: none;
}
.world-weather { position: absolute; inset: 0; pointer-events: none; z-index: 4; }
#game-bottom {
  position: absolute; left: 0; right: 0; bottom: 0; z-index: 20;
  display: flex; align-items: flex-end; justify-content: space-between; gap: 12px;
  padding: 0 14px calc(10px + env(safe-area-inset-bottom)); pointer-events: none;
}
.hint-bar {
  display: flex; align-items: center; gap: 8px; pointer-events: auto;
  background: rgba(8, 13, 24, .82); border: 1px solid rgba(240, 201, 107, .22);
  border-radius: 10px; padding: 7px 12px 7px 7px; max-width: min(620px, 60vw);
  backdrop-filter: blur(8px);
}
.hint-key {
  display: inline-flex; align-items: center; justify-content: center;
  min-width: 24px; height: 24px; padding: 0 6px; border-radius: 6px;
  background: rgba(240, 201, 107, .14); border: 1px solid rgba(240, 201, 107, .45);
  color: var(--gold); font-size: 11px; font-weight: 800;
}
#hint-text { font-size: 11px; color: #d6deeb; line-height: 1.3; }
.team-strip { display: flex; gap: 6px; pointer-events: auto; }
.team-pip {
  position: relative; width: 52px; height: 58px; border-radius: 10px;
  background: rgba(8, 13, 24, .8); border: 1px solid rgba(240, 201, 107, .22);
  display: flex; flex-direction: column; align-items: center; justify-content: flex-end;
  overflow: hidden; padding-bottom: 3px;
}
.team-pip canvas { position: absolute; top: -6px; left: 50%; transform: translateX(-50%); }
.team-pip .pip-hp { width: 80%; height: 3px; border-radius: 3px; background: rgba(255,255,255,.12); overflow: hidden; }
.team-pip .pip-hp i { display: block; height: 100%; background: var(--green); }
.team-pip.fainted { filter: grayscale(1); opacity: .55; }
.team-pip .pip-lvl { position: absolute; top: 2px; right: 4px; font-size: 8px; color: var(--gold); font-weight: 800; }

/* touch */
.touch-controls { display: none; position: absolute; inset: 0; z-index: 18; pointer-events: none; }
.dpad { position: absolute; left: 18px; bottom: 84px; width: 132px; height: 132px; pointer-events: auto; }
.dpad-btn {
  position: absolute; width: 46px; height: 46px; border-radius: 12px;
  border: 1px solid rgba(240, 201, 107, .35); background: rgba(8, 13, 24, .72);
  color: var(--parchment); font-size: 16px; backdrop-filter: blur(6px);
  box-shadow: 0 6px 16px rgba(0,0,0,.3); user-select: none; touch-action: none;
}
.dpad-btn:active, .dpad-btn.pressed { background: rgba(240, 201, 107, .25); border-color: var(--gold); }
.dpad-btn.up { left: 43px; top: 0; }
.dpad-btn.down { left: 43px; bottom: 0; }
.dpad-btn.left { left: 0; top: 43px; }
.dpad-btn.right { right: 0; top: 43px; }
.touch-actions { position: absolute; right: 18px; bottom: 86px; display: flex; align-items: flex-end; gap: 12px; pointer-events: auto; }
.touch-round {
  width: 62px; height: 62px; border-radius: 50%;
  border: 2px solid rgba(240, 201, 107, .55);
  background: radial-gradient(circle at 35% 30%, rgba(240,201,107,.35), rgba(8,13,24,.9));
  color: #fff3c4; font-size: 24px; font-weight: 900;
  box-shadow: 0 8px 22px rgba(0,0,0,.45), 0 0 22px rgba(240,201,107,.15);
  touch-action: none;
}
.touch-round:active { transform: scale(.94); background: radial-gradient(circle at 35% 30%, rgba(240,201,107,.55), rgba(8,13,24,.9)); }
.touch-round.small { width: 44px; height: 44px; font-size: 17px; border-width: 1px; }

/* ------------------------------------------------------------------ */
/* DIALOG */
/* ------------------------------------------------------------------ */
#dialog-root { position: fixed; inset: 0; z-index: 90; pointer-events: none; }
.dialog-layer { position: fixed; inset: 0; display: flex; align-items: flex-end; justify-content: center; padding: 0 16px 20px; pointer-events: none; }
.dialog-layer.leaving { opacity: 0; transition: opacity .14s; }
.dialog-box {
  pointer-events: auto; display: flex; gap: 16px; width: min(940px, 94vw);
  padding: 16px; border-radius: 16px;
  background: linear-gradient(160deg, rgba(18, 28, 48, .98), rgba(8, 13, 24, .99));
  border: 1px solid rgba(240, 201, 107, .42);
  box-shadow: 0 -20px 60px rgba(0,0,0,.6), inset 0 1px 0 rgba(255,255,255,.06);
  cursor: pointer; animation: dialogIn .22s ease both;
}
@keyframes dialogIn { from { opacity: 0; transform: translateY(14px); } to { opacity: 1; transform: none; } }
.dialog-portrait { flex: 0 0 108px; width: 108px; height: 108px; display: flex; align-items: center; justify-content: center; border-radius: 12px; overflow: hidden; background: rgba(240,201,107,.06); border: 1px solid rgba(240,201,107,.18); }
.dialog-portrait.has-art svg { width: 100%; height: 100%; object-fit: cover; }
.dialog-portrait svg { display: block; }
.dialog-medallion {
  width: 78px; height: 78px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-family: var(--serif); font-size: 34px; color: #1a1208;
  background: radial-gradient(circle at 35% 30%, #fff3c4, var(--c, #f0c96b));
  border: 2px solid rgba(255,255,255,.35); box-shadow: 0 0 24px rgba(240,201,107,.3);
}
.dialog-main { flex: 1 1 auto; min-width: 0; display: flex; flex-direction: column; }
.dialog-topline { display: flex; align-items: center; gap: 10px; margin-bottom: 6px; }
.dialog-name { font-family: var(--serif); font-size: 19px; color: var(--gold); }
.dialog-tag { font-size: 9px; text-transform: uppercase; letter-spacing: 1.5px; color: var(--muted); border: 1px solid var(--line-soft); padding: 2px 7px; border-radius: 20px; }
.dialog-text { min-height: 48px; font-size: 14.5px; line-height: 1.55; color: #e6ecf6; white-space: pre-wrap; }
.dialog-text.complete::after { content: "▾"; color: var(--gold); font-size: 12px; margin-left: 4px; animation: blink 1s infinite; }
@keyframes blink { 50% { opacity: .2; } }
.dialog-choices { display: flex; gap: 8px; flex-wrap: wrap; margin-top: 10px; }
.choice-btn {
  display: flex; flex-direction: column; align-items: flex-start; gap: 2px;
  padding: 9px 14px; border-radius: 9px; border: 1px solid rgba(240,201,107,.35);
  background: rgba(24, 35, 58, .9); color: var(--parchment); text-align: left;
  transition: .15s ease;
}
.choice-btn:hover { border-color: var(--gold); background: rgba(240,201,107,.12); transform: translateY(-1px); }
.choice-btn span { font-weight: 700; font-size: 13px; }
.choice-btn small { font-size: 10px; color: var(--muted); }
.dialog-footer { display: flex; align-items: center; justify-content: space-between; margin-top: auto; padding-top: 6px; }
.dialog-hint { font-size: 9.5px; color: var(--muted); letter-spacing: .4px; }
.dialog-next {
  width: 30px; height: 26px; border: 0; background: transparent; color: var(--gold);
  font-size: 14px; opacity: .4; transition: .2s;
}
.dialog-next.ready { opacity: 1; animation: bob 1.2s infinite; }
@keyframes bob { 50% { transform: translateY(4px); } }
.dialog-badge { display: flex; align-items: center; justify-content: center; width: 100%; height: 100%; }

/* ------------------------------------------------------------------ */
/* MODALS */
/* ------------------------------------------------------------------ */
#modal-root { position: fixed; inset: 0; z-index: 80; pointer-events: none; }
.modal-layer { position: fixed; inset: 0; display: flex; align-items: center; justify-content: center; padding: 18px; opacity: 0; transition: opacity .18s ease; pointer-events: none; }
.modal-layer.open { opacity: 1; pointer-events: auto; }
.modal-backdrop { position: absolute; inset: 0; background: rgba(4, 7, 14, .72); backdrop-filter: blur(8px); }
.modal {
  position: relative; z-index: 2; width: min(820px, 96vw); max-height: 90dvh;
  display: flex; flex-direction: column; overflow: hidden;
  transform: translateY(12px) scale(.985); transition: transform .18s ease;
}
.modal-layer.open .modal { transform: none; }
.modal-wide { width: min(1180px, 97vw); }
.modal-head { flex: 0 0 auto; display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 16px 20px 12px; border-bottom: 1px solid var(--line-soft); }
.modal-title { display: flex; align-items: center; gap: 10px; min-width: 0; }
.modal-icon { font-size: 22px; }
.modal-title h2 { font-family: var(--serif); font-size: 22px; letter-spacing: .5px; color: var(--parchment); }
.modal-close {
  width: 34px; height: 34px; border-radius: 50%; border: 1px solid var(--line-soft);
  background: rgba(8,13,24,.6); color: var(--muted); font-size: 14px;
}
.modal-close:hover { color: var(--parchment); border-color: var(--gold); }
.modal-body { flex: 1 1 auto; min-height: 0; overflow-y: auto; padding: 18px 20px 20px; }
.modal-ornament { position: absolute; left: 12px; right: 12px; height: 1px; background: linear-gradient(90deg, transparent, rgba(240,201,107,.45), transparent); pointer-events: none; }
.modal-ornament.top { top: 5px; }
.modal-ornament.bottom { bottom: 5px; }
.section-title { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; margin: 18px 0 10px; }
.section-title h3 { font-family: var(--serif); font-size: 18px; }
.section-title span { font-size: 11px; color: var(--muted); }

/* map */
.map-modal .modal-body { padding: 0; }
.map-layout { display: grid; grid-template-columns: 1fr 330px; min-height: 560px; }
.map-canvas { position: relative; min-height: 520px; background: #0d2233; display: flex; align-items: center; justify-content: center; padding: 8px; }
.world-map { width: 100%; height: 100%; max-height: 74dvh; display: block; }
.map-node { cursor: pointer; transition: filter .15s ease; }
.map-node:hover { filter: brightness(1.25); }
.map-node.locked { cursor: not-allowed; }
.map-node.selected circle:nth-of-type(1) { stroke: #fff3c4; stroke-width: 5; }
.map-pulse { animation: mapPulse 2.2s infinite; }
@keyframes mapPulse { 0% { opacity: .8; transform: scale(.9); } 70% { opacity: 0; transform: scale(1.35); } 100% { opacity: 0; } }
.map-side { padding: 18px; border-left: 1px solid var(--line-soft); background: rgba(8, 13, 24, .45); overflow-y: auto; }
.map-side-head h3 { font-family: var(--serif); font-size: 24px; margin: 3px 0 4px; }
.map-side-head p { font-size: 12px; line-height: 1.45; }
.badge-row { display: flex; gap: 4px; flex-wrap: wrap; margin: 14px 0 16px; }
.map-detail-card { border: 1px solid var(--line-soft); border-radius: 12px; padding: 12px; background: rgba(10,16,30,.5); }
.map-detail-card.locked { border-color: rgba(120,130,150,.2); }
.detail-title { display: flex; gap: 10px; align-items: center; }
.detail-icon { font-size: 26px; }
.detail-title h3 { font-family: var(--serif); font-size: 18px; }
.detail-title small { font-size: 10px; color: var(--muted); }
.map-detail-card p { font-size: 11.5px; color: #b9c5d8; line-height: 1.45; margin: 8px 0 10px; }
.detail-line { display: flex; justify-content: space-between; gap: 10px; font-size: 11px; padding: 4px 0; border-top: 1px solid rgba(255,255,255,.04); }
.detail-line span { color: var(--muted); }
.detail-line strong { color: var(--parchment); }
.lock-note { margin-top: 8px; font-size: 11px; color: #ffb08a; line-height: 1.45; background: rgba(228,87,46,.08); border: 1px solid rgba(228,87,46,.2); border-radius: 8px; padding: 8px; }
.current-tag { margin-top: 8px; text-align: center; font-size: 11px; color: var(--gold); border: 1px dashed rgba(240,201,107,.4); border-radius: 8px; padding: 7px; }
.map-detail-card .btn { margin-top: 10px; }
.map-legend { display: flex; flex-wrap: wrap; gap: 10px; margin-top: 14px; font-size: 10px; color: var(--muted); }
.map-legend span { display: inline-flex; align-items: center; gap: 5px; }
.dot { width: 8px; height: 8px; border-radius: 50%; display: inline-block; }
.dot.current { background: var(--gold); box-shadow: 0 0 8px var(--gold); }
.dot.open { background: #7de0d8; }
.dot.locked { background: #5a6478; }

/* trainer card */
.card-modal .modal-body { background: radial-gradient(circle at 20% 0%, rgba(240,201,107,.06), transparent 45%); }
.trainer-card-wrap { display: grid; grid-template-columns: 1.15fr .85fr; gap: 18px; }
.trainer-card {
  position: relative; overflow: hidden; border-radius: 18px; padding: 18px;
  background:
    radial-gradient(circle at 80% 10%, rgba(240,201,107,.22), transparent 40%),
    linear-gradient(145deg, #2a3550, #101827 55%, #1d2a44);
  border: 1px solid rgba(240,201,107,.45);
  box-shadow: inset 0 0 40px rgba(0,0,0,.35), 0 20px 40px rgba(0,0,0,.35);
}
.tc-shine { position: absolute; inset: -40%; background: linear-gradient(115deg, transparent 35%, rgba(255,255,255,.12) 48%, transparent 60%); transform: translateX(-30%); animation: shine 5s infinite; pointer-events: none; }
@keyframes shine { 0%,60% { transform: translateX(-45%); } 100% { transform: translateX(45%); } }
.tc-top { display: flex; justify-content: space-between; gap: 10px; font-size: 9px; letter-spacing: 2px; color: var(--gold); border-bottom: 1px solid rgba(240,201,107,.25); padding-bottom: 8px; }
.tc-id { color: var(--muted); letter-spacing: 1px; }
.tc-main { display: flex; gap: 14px; align-items: center; margin: 16px 0 12px; }
.tc-avatar { width: 118px; height: 118px; flex: 0 0 118px; border-radius: 50%; overflow: hidden; border: 2px solid rgba(240,201,107,.5); box-shadow: 0 0 30px rgba(240,201,107,.12); }
.tc-avatar svg { width: 100%; height: 100%; }
.tc-identity h2 { font-family: var(--serif); font-size: 30px; line-height: 1; color: #fff3c4; }
.tc-meta { display: flex; flex-wrap: wrap; gap: 6px 12px; font-size: 11px; color: #c9d3e4; margin: 6px 0; }
.tc-rank { font-size: 11px; color: var(--muted); }
.tc-badges { display: flex; gap: 5px; flex-wrap: wrap; padding: 10px 0; border-top: 1px solid rgba(240,201,107,.18); border-bottom: 1px solid rgba(240,201,107,.18); }
.tc-stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 6px; padding: 12px 0 6px; }
.tc-stats div { display: flex; flex-direction: column; gap: 2px; }
.tc-stats span { font-size: 9px; text-transform: uppercase; letter-spacing: .8px; color: var(--muted); }
.tc-stats strong { font-size: 17px; color: var(--parchment); }
.tc-footer { display: flex; justify-content: space-between; gap: 10px; border-top: 1px solid rgba(240,201,107,.18); padding-top: 9px; margin-top: 6px; font-size: 9.5px; color: var(--muted); }
.card-side h3 { font-family: var(--serif); font-size: 18px; margin-bottom: 8px; }
.card-team { display: grid; gap: 6px; }
.card-mon { display: flex; gap: 8px; align-items: center; padding: 5px; border: 1px solid var(--line-soft); border-radius: 10px; background: rgba(8,13,24,.35); }
.card-mon-art { width: 66px; height: 66px; flex: 0 0 66px; }
.card-mon-info { flex: 1; min-width: 0; }
.card-mon-info strong { display: block; font-size: 12px; }
.card-mon-info span { font-size: 9.5px; color: var(--muted); }
.card-actions { display: grid; gap: 7px; margin-top: 12px; }
.save-note { font-size: 9.5px; color: var(--muted); margin-top: 8px; text-align: center; }
.badge-medal {
  display: inline-flex; align-items: center; justify-content: center; border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, rgba(255,255,255,.35), var(--badge));
  border: 2px solid rgba(255,255,255,.25);
  box-shadow: 0 0 14px color-mix(in srgb, var(--badge) 40%, transparent), inset 0 -3px 8px rgba(0,0,0,.3);
  color: #2b1a08; flex: 0 0 auto;
}
.badge-medal.locked { background: rgba(255,255,255,.06); border-color: rgba(255,255,255,.12); box-shadow: none; color: rgba(255,255,255,.15); filter: grayscale(1); }
.badge-glyph { font-size: 17px; font-weight: 900; text-shadow: 0 1px 0 rgba(255,255,255,.3); }

/* team */
.team-layout { display: grid; grid-template-columns: 330px 1fr; gap: 16px; }
.team-list { display: grid; gap: 7px; align-content: start; }
.team-slot {
  display: flex; align-items: center; gap: 9px; width: 100%; text-align: left;
  padding: 7px; border-radius: 11px; border: 1px solid var(--line-soft);
  background: rgba(8,13,24,.4); color: var(--text); position: relative;
}
.team-slot:hover { border-color: rgba(240,201,107,.4); }
.team-slot.active { border-color: var(--gold); background: rgba(240,201,107,.08); }
.team-slot.fainted { opacity: .55; }
.slot-index { position: absolute; top: 4px; left: 6px; font-size: 8px; color: var(--muted); }
.slot-art { width: 54px; height: 54px; flex: 0 0 54px; display: flex; align-items: center; justify-content: center; }
.slot-main { flex: 1; min-width: 0; }
.slot-main strong { display: block; font-size: 12px; }
.slot-main small { display: block; font-size: 9px; color: var(--muted); margin-bottom: 3px; }
.status-dot { width: 18px; height: 18px; border-radius: 50%; display: inline-flex; align-items: center; justify-content: center; font-size: 8px; font-weight: 800; background: #6b5b95; color: #fff; }
.status-dot.brulure { background: #e4572e; }
.status-dot.paralysie { background: #f2c53d; color: #2b1a08; }
.status-dot.sommeil { background: #6b5b95; }
.status-dot.poison { background: #8a3ab8; }
.team-detail-wrap { min-width: 0; }
.team-detail { border: 1px solid var(--line-soft); border-radius: 12px; padding: 12px; background: rgba(8,13,24,.35); }
.td-head { display: flex; gap: 12px; }
.td-art { width: 100px; height: 100px; flex: 0 0 100px; }
.td-head h3 { font-family: var(--serif); font-size: 22px; }
.td-head p { font-size: 10.5px; line-height: 1.4; }
.td-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 5px; margin: 10px 0; }
.td-stats span { display: flex; justify-content: space-between; font-size: 10px; color: var(--muted); border: 1px solid rgba(255,255,255,.05); border-radius: 6px; padding: 5px 7px; }
.td-stats b { color: var(--parchment); }
.xp-row { display: flex; align-items: center; gap: 8px; margin: 8px 0 10px; font-size: 9px; color: var(--muted); }
.xp-track { flex: 1; height: 4px; border-radius: 4px; background: rgba(255,255,255,.1); overflow: hidden; }
.xp-fill { height: 100%; background: linear-gradient(90deg, #7de0d8, #4b8ef7); border-radius: 4px; }
.move-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 5px; }
.move-mini { border: 1px solid rgba(255,255,255,.07); border-radius: 8px; padding: 6px 8px; background: rgba(255,255,255,.02); }
.move-mini strong { display: block; font-size: 11px; }
.move-mini small { font-size: 8.5px; color: var(--muted); }
.td-actions { display: flex; gap: 5px; flex-wrap: wrap; margin-top: 10px; }
.box-section { margin-top: 18px; }
.box-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(170px, 1fr)); gap: 6px; }
.box-slot { display: flex; align-items: center; gap: 6px; padding: 6px; border: 1px solid var(--line-soft); border-radius: 9px; background: rgba(8,13,24,.3); }
.box-slot .slot-art { width: 42px; height: 42px; flex-basis: 42px; }
.box-slot span:nth-child(2) { flex: 1; min-width: 0; }
.box-slot strong { display: block; font-size: 11px; }
.box-slot small { display: block; font-size: 8.5px; color: var(--muted); }
.xp-row.small { margin: 0; }
.xp-row.small .xp-track { height: 3px; }

/* bag / shop */
.bag-head, .shop-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 12px; margin-bottom: 14px; padding-bottom: 10px; border-bottom: 1px solid var(--line-soft); }
.bag-head h3, .shop-head h3 { font-family: var(--serif); font-size: 24px; color: var(--gold); }
.bag-count, .shop-badge { font-size: 10px; color: var(--muted); border: 1px solid var(--line-soft); border-radius: 20px; padding: 4px 9px; }
.item-list, .shop-grid { display: grid; gap: 6px; }
.item-row, .shop-item { display: flex; align-items: center; gap: 10px; padding: 8px; border: 1px solid var(--line-soft); border-radius: 10px; background: rgba(8,13,24,.35); }
.item-icon { width: 38px; height: 38px; flex: 0 0 38px; display: flex; align-items: center; justify-content: center; font-size: 21px; border-radius: 9px; background: rgba(240,201,107,.08); border: 1px solid rgba(240,201,107,.15); }
.item-main { flex: 1; min-width: 0; }
.item-main strong { display: block; font-size: 12px; }
.item-main small { display: block; font-size: 9.5px; color: var(--muted); line-height: 1.35; }
.item-count { font-size: 12px; color: var(--gold); font-weight: 700; }
.price { display: inline-block; margin-top: 2px; font-size: 10px; color: var(--gold); }
.bag-team { margin-top: 16px; }
.bag-team h3 { font-family: var(--serif); font-size: 16px; margin-bottom: 8px; }
.bag-mon { display: flex; align-items: center; gap: 8px; padding: 5px 0; border-top: 1px solid rgba(255,255,255,.04); }
.bag-mon .slot-art { width: 44px; height: 44px; flex-basis: 44px; }
.bag-mon span:nth-child(2) { width: 120px; }
.bag-mon strong { display: block; font-size: 11px; }
.bag-mon small { display: block; font-size: 8.5px; color: var(--muted); }
.bag-mon .hp-line { flex: 1; }

/* friends */
.friends-head { display: flex; justify-content: space-between; align-items: flex-start; gap: 12px; margin-bottom: 14px; }
.friends-head h3 { font-family: var(--serif); font-size: 24px; }
.friends-head p { font-size: 11px; margin-top: 4px; max-width: 520px; }
.friend-count-big { font-family: var(--serif); font-size: 46px; color: rgba(240,201,107,.35); line-height: 1; }
.friend-list { display: grid; gap: 7px; }
.friend-card { display: flex; align-items: center; gap: 10px; padding: 8px; border: 1px solid var(--line-soft); border-radius: 12px; background: rgba(8,13,24,.35); }
.friend-avatar { width: 58px; height: 58px; flex: 0 0 58px; border-radius: 50%; overflow: hidden; }
.friend-avatar svg { width: 100%; height: 100%; }
.friend-avatar.professor { display: flex; align-items: center; justify-content: center; background: radial-gradient(circle at 35% 30%, #fff3c4, #c9a45a); color: #2b1a08; font-family: var(--serif); font-size: 28px; border: 2px solid rgba(255,255,255,.3); }
.friend-avatar.generic { display: flex; align-items: center; justify-content: center; background: var(--c); color: #fff; font-family: var(--serif); font-size: 26px; }
.friend-main { flex: 1; min-width: 0; }
.friend-main strong { display: block; font-size: 13px; }
.friend-main small { display: block; font-size: 9.5px; color: var(--muted); }
.friend-meta { display: flex; align-items: center; gap: 8px; font-size: 9px; color: var(--muted); margin-top: 3px; flex-wrap: wrap; }
.hearts { letter-spacing: 1px; color: rgba(255,255,255,.15); }
.hearts .on { color: #f08a8a; }
.friend-actions { display: flex; gap: 5px; flex-wrap: wrap; justify-content: flex-end; }

/* online */
.maintenance-banner {
  display: flex; align-items: center; gap: 10px; padding: 10px 12px;
  border-radius: 11px; background: rgba(228, 87, 46, .08);
  border: 1px solid rgba(228, 87, 46, .28); margin-bottom: 12px;
}
.maint-dot { width: 9px; height: 9px; border-radius: 50%; background: #ff7a4d; box-shadow: 0 0 12px #ff7a4d; animation: pulse 1.6s infinite; flex: 0 0 auto; }
.maintenance-banner div { flex: 1; }
.maintenance-banner strong { display: block; font-size: 12px; color: #ffb08a; }
.maintenance-banner small { display: block; font-size: 10px; color: var(--muted); }
.maint-lock { font-size: 18px; }
.tab-row { display: flex; gap: 5px; margin-bottom: 14px; border-bottom: 1px solid var(--line-soft); padding-bottom: 8px; }
.tab { border: 1px solid transparent; background: transparent; color: var(--muted); padding: 7px 12px; border-radius: 8px; font-size: 11px; font-weight: 700; }
.tab:hover { color: var(--parchment); background: rgba(255,255,255,.04); }
.tab.active { color: var(--gold); border-color: rgba(240,201,107,.35); background: rgba(240,201,107,.08); }
.online-rank { display: flex; align-items: center; gap: 14px; padding: 14px; border: 1px solid var(--line-soft); border-radius: 12px; background: rgba(8,13,24,.35); }
.rank-emblem { width: 64px; height: 64px; flex: 0 0 64px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-family: var(--serif); font-size: 28px; color: #1a1208; background: radial-gradient(circle at 35% 30%, #fff, var(--rc)); border: 2px solid rgba(255,255,255,.3); box-shadow: 0 0 24px color-mix(in srgb, var(--rc) 45%, transparent); }
.rank-main { flex: 1; min-width: 0; }
.rank-main h3 { font-family: var(--serif); font-size: 24px; }
.rank-progress { height: 6px; border-radius: 6px; background: rgba(255,255,255,.1); overflow: hidden; margin: 6px 0 4px; }
.rank-progress div { height: 100%; border-radius: 6px; }
.rank-main small { font-size: 9.5px; color: var(--muted); }
.rank-record { display: flex; flex-direction: column; gap: 2px; font-size: 10px; color: var(--muted); text-align: right; }
.rank-record b { color: var(--parchment); font-size: 15px; }
.league-info { display: grid; grid-template-columns: repeat(3, 1fr); gap: 7px; margin: 12px 0; }
.info-tile { border: 1px solid var(--line-soft); border-radius: 9px; padding: 9px; background: rgba(8,13,24,.3); }
.info-tile span { display: block; font-size: 8.5px; text-transform: uppercase; letter-spacing: .8px; color: var(--muted); }
.info-tile strong { display: block; font-size: 12px; margin: 2px 0; }
.info-tile small { display: block; font-size: 9px; color: var(--gold); }
.online-modal .btn.full { margin-top: 4px; }
.locked-feature { text-align: center; padding: 10px 0; }
.lock-orb { width: 66px; height: 66px; margin: 0 auto 10px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 28px; background: rgba(240,201,107,.08); border: 1px solid rgba(240,201,107,.25); }
.locked-feature h3 { font-family: var(--serif); font-size: 20px; margin-bottom: 4px; }
.locked-feature p { font-size: 11.5px; color: var(--muted); max-width: 440px; margin: 0 auto 12px; line-height: 1.5; }
.fake-chat { text-align: left; border: 1px solid var(--line-soft); border-radius: 9px; padding: 9px; background: rgba(8,13,24,.35); margin: 0 auto 8px; max-width: 440px; font-size: 10.5px; color: #b9c5d8; }
.fake-chat b { color: var(--gold); }
.disabled-input { max-width: 440px; margin: 0 auto; display: flex; justify-content: space-between; padding: 10px 12px; border-radius: 9px; border: 1px dashed rgba(255,255,255,.12); color: rgba(255,255,255,.3); font-size: 11px; }
.trade-preview { display: flex; align-items: center; justify-content: center; gap: 22px; margin: 10px 0 14px; }
.trade-side { display: flex; flex-direction: column; align-items: center; gap: 5px; font-size: 10px; color: var(--muted); }
.trade-ball { width: 64px; height: 64px; border-radius: 50%; display: flex; align-items: center; justify-content: center; background: rgba(240,201,107,.06); border: 1px solid var(--line-soft); }
.trade-arrows { font-size: 24px; color: var(--gold); }
.online-footer { display: flex; justify-content: space-between; gap: 10px; border-top: 1px solid var(--line-soft); margin-top: 14px; padding-top: 9px; font-size: 9.5px; color: var(--muted); }
.online-footer b { color: var(--parchment); }

/* settings / help / ending */
.setting-row { display: flex; align-items: center; justify-content: space-between; gap: 14px; padding: 11px 0; border-bottom: 1px solid rgba(255,255,255,.05); }
.setting-row strong { display: block; font-size: 12px; }
.setting-row small { display: block; font-size: 9.5px; color: var(--muted); }
.danger-row strong { color: #ffb08a; }
.toggle { width: 46px; height: 26px; border-radius: 20px; border: 1px solid rgba(255,255,255,.15); background: rgba(255,255,255,.08); padding: 2px; transition: .18s; }
.toggle span { display: block; width: 20px; height: 20px; border-radius: 50%; background: #7a8498; transition: .18s; }
.toggle.on { background: rgba(240,201,107,.2); border-color: rgba(240,201,107,.55); }
.toggle.on span { transform: translateX(20px); background: var(--gold); box-shadow: 0 0 10px rgba(240,201,107,.5); }
.credits-box { margin-top: 16px; padding: 12px; border: 1px solid var(--line-soft); border-radius: 10px; background: rgba(8,13,24,.3); display: grid; gap: 3px; }
.credits-box strong { font-family: var(--serif); color: var(--gold); }
.credits-box span { font-size: 9.5px; color: var(--muted); }
.help-objective { padding: 12px; border: 1px solid var(--line); border-radius: 11px; background: rgba(240,201,107,.06); margin-bottom: 14px; }
.help-objective h3 { font-family: var(--serif); font-size: 18px; margin-top: 2px; }
.help-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
.help-card { border: 1px solid var(--line-soft); border-radius: 10px; padding: 10px; background: rgba(8,13,24,.3); }
.help-card h4 { font-family: var(--serif); font-size: 14px; color: var(--gold); margin-bottom: 4px; }
.help-card p { font-size: 10.5px; color: #b9c5d8; line-height: 1.45; }
.help-tip { margin-top: 12px; padding: 10px; border-left: 2px solid var(--gold2); background: rgba(240,201,107,.05); font-size: 11px; color: #d6deeb; line-height: 1.45; }
.help-tip strong { color: var(--gold); }
.ending { text-align: center; padding: 6px 0; }
.ending-crown { font-size: 64px; color: var(--gold); text-shadow: 0 0 40px rgba(240,201,107,.5); }
.ending h2 { font-family: var(--serif); font-size: 38px; color: #fff3c4; }
.ending-title { color: var(--gold); font-size: 12px; letter-spacing: 2px; text-transform: uppercase; margin: 4px 0 14px; }
.ending-badges { display: flex; justify-content: center; gap: 4px; flex-wrap: wrap; margin-bottom: 14px; }
.ending-stats { display: grid; grid-template-columns: repeat(5, 1fr); gap: 5px; margin: 12px 0; }
.ending-stats div { border: 1px solid var(--line-soft); border-radius: 8px; padding: 8px 4px; }
.ending-stats span { display: block; font-size: 8px; color: var(--muted); text-transform: uppercase; }
.ending-stats strong { display: block; font-size: 14px; color: var(--parchment); }
.ending-lore { font-family: var(--serif); font-size: 14px; color: #d6deeb; line-height: 1.5; margin: 14px 0; }

/* pause menu */
.pause-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 7px; }
.pause-grid .btn { justify-content: flex-start; }
.pause-save { margin-top: 12px; font-size: 10px; color: var(--muted); text-align: center; }

/* type chips */
.type-row { display: flex; gap: 4px; flex-wrap: wrap; }
.type-chip {
  display: inline-flex; align-items: center; gap: 3px;
  padding: 3px 7px; border-radius: 20px; font-size: 9px; font-weight: 700;
  color: #fff; background: color-mix(in srgb, var(--tc) 28%, #0b1120);
  border: 1px solid color-mix(in srgb, var(--tc) 55%, transparent);
  white-space: nowrap;
}
.type-chip.small { font-size: 8px; padding: 2px 5px; }

/* hp */
.hp-line { display: flex; align-items: center; gap: 6px; }
.hp-track { flex: 1; height: 6px; border-radius: 6px; background: rgba(255,255,255,.12); overflow: hidden; }
.hp-fill { height: 100%; border-radius: 6px; background: linear-gradient(90deg, #6ee7a0, #3fae6a); transition: width .5s ease; }
.hp-line.warn .hp-fill { background: linear-gradient(90deg, #f2c53d, #e09a2a); }
.hp-line.danger .hp-fill { background: linear-gradient(90deg, #ff7a5c, #c92e2e); }
.hp-text { font-size: 9px; color: var(--muted); white-space: nowrap; }

/* toasts */
#toast-root { position: fixed; top: calc(76px + env(safe-area-inset-top)); left: 50%; transform: translateX(-50%); z-index: 120; display: flex; flex-direction: column; align-items: center; gap: 6px; pointer-events: none; width: min(440px, 92vw); }
.toast {
  display: flex; align-items: center; gap: 8px; padding: 9px 14px; border-radius: 30px;
  background: rgba(8, 13, 24, .94); border: 1px solid rgba(240,201,107,.5);
  color: var(--parchment); font-size: 11.5px; box-shadow: 0 12px 30px rgba(0,0,0,.45);
  animation: toastIn .25s ease both;
}
.toast.out { animation: toastOut .35s ease both; }
.toast-icon { font-size: 15px; }
@keyframes toastIn { from { opacity: 0; transform: translateY(-8px); } to { opacity: 1; transform: none; } }
@keyframes toastOut { to { opacity: 0; transform: translateY(-8px); } }

/* ------------------------------------------------------------------ */
/* BATTLE */
/* ------------------------------------------------------------------ */
#battle-root { position: fixed; inset: 0; z-index: 70; pointer-events: none; }
.battle-screen { position: fixed; inset: 0; overflow: hidden; background: #0a1024; pointer-events: auto; }
.battle-screen.leaving { opacity: 0; transition: opacity .3s ease; }
#battle-canvas { position: absolute; inset: 0; width: 100%; height: 100%; display: block; }
.battle-vignette { position: absolute; inset: 0; background: radial-gradient(circle at 50% 50%, transparent 45%, rgba(0,0,0,.4)); pointer-events: none; }
.battle-top { position: absolute; top: 12px; left: 14px; right: 14px; display: flex; justify-content: space-between; align-items: flex-start; gap: 10px; z-index: 3; pointer-events: none; }
.battle-log { width: min(430px, 48vw); max-height: 120px; overflow: hidden; padding: 9px 11px; border-radius: 10px; background: rgba(8,13,24,.78); border: 1px solid rgba(240,201,107,.22); backdrop-filter: blur(8px); }
.log-line { font-size: 10.5px; line-height: 1.35; color: #d6deeb; padding: 1px 0; }
.log-line.important { color: var(--gold); font-weight: 700; }
.log-line.action { color: #fff; }
.log-line.super { color: #ffd166; font-weight: 700; }
.log-line.weak { color: #9aa7bd; }
.log-line.crit { color: #ff8a65; font-weight: 700; }
.log-line.status { color: #c9a8ff; }
.log-line.faint { color: #ff7a5c; font-weight: 700; }
.log-line.heal { color: #7de0a0; }
.log-line.mega { color: #7df9ff; font-weight: 700; }
.battle-tag { padding: 5px 10px; border-radius: 20px; background: rgba(8,13,24,.7); border: 1px solid rgba(240,201,107,.28); font-size: 9px; letter-spacing: 1.2px; text-transform: uppercase; color: var(--gold); }
.info-card {
  position: absolute; z-index: 3; width: min(310px, 42vw);
  padding: 9px 11px; border-radius: 11px;
  background: rgba(8,13,24,.82); border: 1px solid rgba(240,201,107,.3);
  backdrop-filter: blur(8px); box-shadow: 0 10px 26px rgba(0,0,0,.35);
}
.enemy-card { top: 74px; right: 16px; }
.ally-card { bottom: 190px; left: 16px; }
.info-head { display: flex; justify-content: space-between; align-items: baseline; gap: 8px; }
.info-head strong { font-family: var(--serif); font-size: 15px; }
.info-head span { font-size: 10px; color: var(--muted); }
.info-card .type-row { margin: 4px 0 5px; }
.status-chip { display: inline-block; margin-top: 4px; font-size: 8px; text-transform: uppercase; letter-spacing: .6px; padding: 2px 6px; border-radius: 10px; background: rgba(107,91,149,.3); border: 1px solid rgba(107,91,149,.6); color: #d6c8ff; }
.status-chip.brulure { background: rgba(228,87,46,.22); border-color: rgba(228,87,46,.6); color: #ffb08a; }
.status-chip.paralysie { background: rgba(242,197,61,.18); border-color: rgba(242,197,61,.6); color: #ffe08a; }
.status-chip.poison { background: rgba(138,58,184,.2); border-color: rgba(138,58,184,.6); color: #d8a8ff; }
.mega-chip { display: inline-block; margin-left: 5px; margin-top: 4px; font-size: 8px; padding: 2px 6px; border-radius: 10px; background: rgba(125,249,255,.16); border: 1px solid rgba(125,249,255,.6); color: #7df9ff; font-weight: 800; }
.battle-command {
  position: absolute; right: 16px; bottom: 16px; z-index: 4;
  width: min(570px, 58vw); padding: 10px; display: flex; flex-direction: column; gap: 7px;
  background: linear-gradient(160deg, rgba(18,28,48,.97), rgba(8,13,24,.98));
  border: 1px solid rgba(240,201,107,.35); border-radius: 14px;
  box-shadow: 0 18px 50px rgba(0,0,0,.5);
}
.move-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 5px; }
.move-btn {
  display: flex; flex-direction: column; align-items: flex-start; gap: 2px;
  padding: 7px 9px; border-radius: 8px; border: 1px solid rgba(255,255,255,.08);
  border-left: 4px solid var(--tc); background: rgba(255,255,255,.035);
  color: var(--text); text-align: left; transition: .13s ease; min-height: 44px;
}
.move-btn:hover:not(:disabled) { background: rgba(255,255,255,.08); transform: translateY(-1px); border-color: var(--tc); }
.move-name { font-size: 11.5px; font-weight: 700; }
.move-meta { font-size: 8.5px; color: var(--muted); }
.action-row { display: grid; grid-template-columns: repeat(4, 1fr); gap: 5px; }
.action-btn {
  display: flex; align-items: center; justify-content: center; gap: 4px;
  padding: 6px 4px; border-radius: 8px; border: 1px solid rgba(240,201,107,.18);
  background: rgba(10,16,30,.7); color: #d6deeb; font-size: 14px;
}
.action-btn span { font-size: 9px; font-weight: 700; }
.action-btn:hover:not(:disabled) { border-color: rgba(240,201,107,.5); background: rgba(240,201,107,.08); }
.action-btn.mega.available { border-color: rgba(125,249,255,.5); color: #7df9ff; box-shadow: 0 0 14px rgba(125,249,255,.12); }
.battle-subpanel {
  position: absolute; right: 16px; bottom: 16px; z-index: 5;
  width: min(570px, 58vw); max-height: 72vh; overflow: auto;
  opacity: 0; pointer-events: none; transform: translateY(8px); transition: .16s ease;
}
.battle-subpanel.open { opacity: 1; pointer-events: auto; transform: none; }
.subpanel-card { padding: 10px; border-radius: 12px; background: linear-gradient(160deg, rgba(18,28,48,.99), rgba(8,13,24,.99)); border: 1px solid rgba(240,201,107,.35); box-shadow: 0 18px 50px rgba(0,0,0,.55); }
.subpanel-head { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-bottom: 7px; }
.subpanel-head h3 { font-family: var(--serif); font-size: 16px; }
.switch-list, .bag-list { display: grid; gap: 4px; }
.switch-row { display: flex; align-items: center; gap: 7px; width: 100%; padding: 6px 8px; border-radius: 7px; border: 1px solid rgba(255,255,255,.06); background: rgba(255,255,255,.025); color: var(--text); text-align: left; }
.switch-row:hover:not(:disabled) { border-color: rgba(240,201,107,.4); background: rgba(240,201,107,.06); }
.switch-row.active { border-color: rgba(240,201,107,.4); }
.switch-dot { width: 9px; height: 9px; border-radius: 50%; flex: 0 0 9px; }
.switch-main { flex: 1; min-width: 0; }
.switch-main strong { display: block; font-size: 11px; }
.switch-main small { display: block; font-size: 8.5px; color: var(--muted); }
.switch-types { display: flex; gap: 3px; }
.switch-types i { width: 15px; height: 15px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-style: normal; font-size: 7px; color: #fff; font-weight: 800; }
.bag-row { display: flex; align-items: center; gap: 8px; width: 100%; padding: 6px 8px; border-radius: 7px; border: 1px solid rgba(255,255,255,.06); background: rgba(255,255,255,.025); color: var(--text); text-align: left; }
.bag-row:hover:not(:disabled) { border-color: rgba(240,201,107,.4); background: rgba(240,201,107,.06); }
.bag-icon { font-size: 18px; }
.bag-main { flex: 1; min-width: 0; }
.bag-main strong { display: block; font-size: 11px; }
.bag-main small { display: block; font-size: 8.5px; color: var(--muted); }
.bag-count { font-size: 10px; color: var(--gold); }

/* battle splash */
.battle-splash {
  position: absolute; inset: 0; z-index: 8; display: flex; align-items: center; justify-content: center;
  background: radial-gradient(circle at 50% 45%, rgba(15,22,38,.6), rgba(4,7,14,.92));
  opacity: 0; pointer-events: none; transition: opacity .25s ease;
}
.battle-splash.show { opacity: 1; }
.splash-inner { text-align: center; animation: splashIn .5s ease both; }
@keyframes splashIn { from { opacity: 0; transform: scale(.9); } to { opacity: 1; transform: none; } }
.splash-vs { font-family: var(--serif); font-size: clamp(54px, 12vw, 120px); color: var(--gold); line-height: .8; text-shadow: 0 0 40px rgba(240,201,107,.5), 0 6px 0 #5c3a1f; }
.splash-names { display: flex; align-items: center; justify-content: center; gap: 14px; margin: 14px 0 4px; font-family: var(--serif); font-size: clamp(16px, 2.4vw, 24px); color: #fff3c4; }
.splash-names i { color: var(--gold); font-style: normal; }
.splash-sub { font-size: 10px; letter-spacing: 3px; text-transform: uppercase; color: var(--muted); }

/* battle result */
.battle-result {
  position: absolute; inset: 0; z-index: 10; display: flex; align-items: center; justify-content: center;
  background: rgba(4,7,14,.7); backdrop-filter: blur(6px); opacity: 0; pointer-events: none; transition: opacity .2s;
}
.battle-result.show { opacity: 1; pointer-events: auto; }
.result-card {
  width: min(480px, 92vw); text-align: center; padding: 22px;
  border-radius: 18px; background: linear-gradient(160deg, rgba(24,35,58,.99), rgba(8,13,24,.99));
  border: 1px solid rgba(240,201,107,.45); box-shadow: 0 30px 80px rgba(0,0,0,.65);
  animation: resultIn .3s ease both;
}
@keyframes resultIn { from { opacity: 0; transform: translateY(14px) scale(.97); } to { opacity: 1; transform: none; } }
.result-icon { font-size: 50px; line-height: 1; margin-bottom: 6px; }
.result-card h2 { font-family: var(--serif); font-size: 28px; color: #fff3c4; }
.result-sub { font-size: 12px; color: var(--muted); margin: 4px 0 12px; }
.result-lines { display: grid; gap: 4px; margin: 0 0 16px; font-size: 11px; color: #d6deeb; }
.result-lines div { padding: 4px 8px; border-radius: 6px; background: rgba(255,255,255,.03); }

/* ball throw */
.ball-throw { position: absolute; left: 50%; top: 50%; z-index: 9; transform: translate(-50%, -50%); animation: ballThrow 1.2s ease-in-out both; filter: drop-shadow(0 10px 14px rgba(0,0,0,.5)); }
.ball-throw.caught { animation: ballCatch .9s ease both; }
.ball-throw.escaped { animation: ballEscape .9s ease both; }
@keyframes ballThrow {
  0% { transform: translate(0, 180px) scale(.6) rotate(0); opacity: 0; }
  45% { transform: translate(80px, -160px) scale(1.1) rotate(280deg); opacity: 1; }
  70% { transform: translate(130px, -60px) scale(1) rotate(420deg); }
  100% { transform: translate(150px, 0) scale(1) rotate(500deg); }
}
@keyframes ballCatch {
  0% { transform: translate(150px, 0) scale(1) rotate(500deg); }
  30% { transform: translate(150px, 0) scale(1.15) rotate(540deg); }
  45% { transform: translate(150px, 0) scale(1) rotate(540deg); }
  100% { transform: translate(150px, 0) scale(1) rotate(540deg); opacity: 1; }
}
@keyframes ballEscape {
  0% { transform: translate(150px, 0) scale(1) rotate(540deg); opacity: 1; }
  100% { transform: translate(150px, 0) scale(1.4) rotate(540deg); opacity: 0; }
}

/* responsive */
@media (max-width: 1100px) {
  .intro-layout { grid-template-columns: .8fr 1.2fr; gap: 16px; }
  .trainer-card-wrap { grid-template-columns: 1fr; }
  .team-layout { grid-template-columns: 290px 1fr; }
  .map-layout { grid-template-columns: 1fr 290px; }
}
@media (max-width: 860px) {
  .intro-layout { grid-template-columns: 1fr; height: 92dvh; overflow-y: auto; align-items: start; }
  .intro-art { height: 260px; align-items: center; }
  .professor-art { width: min(300px, 70vw); }
  .intro-panel { height: auto; max-height: none; }
  .intro-text { min-height: 120px; flex: none; }
  .starter-grid { grid-template-columns: 1fr; }
  .starter-card { display: grid; grid-template-columns: 70px 1fr; text-align: left; align-items: center; }
  .starter-art { grid-row: span 3; }
  .starter-card small { min-height: 0; }
  .map-layout { grid-template-columns: 1fr; }
  .map-canvas { min-height: 380px; }
  .map-side { border-left: 0; border-top: 1px solid var(--line-soft); }
  .team-layout { grid-template-columns: 1fr; }
  .team-list { grid-template-columns: 1fr 1fr; }
  .help-grid { grid-template-columns: 1fr; }
  .ending-stats { grid-template-columns: repeat(3, 1fr); }
  .hud-objective { display: none; }
  .hud-btn small { display: none; }
  .hud-btn { min-width: 36px; height: 36px; }
  .hud-btn span { font-size: 16px; }
  .team-strip { display: none; }
  .world-controls-hint { display: none; }
  .touch-controls { display: block; }
  .battle-log { width: min(320px, 56vw); max-height: 92px; }
  .battle-command { width: min(480px, 64vw); }
  .battle-subpanel { width: min(480px, 64vw); }
}
@media (max-width: 640px) {
  #hud { padding: 6px 8px calc(6px + env(safe-area-inset-top)); gap: 6px; }
  .hud-left { gap: 7px; }
  .hud-location h2 { font-size: 15px; }
  .hud-location small { display: none; }
  .hud-badges { gap: 1px; }
  .hud-badges .badge-medal { width: 15px !important; height: 15px !important; }
  .hud-badges .badge-glyph { font-size: 7px; }
  .hud-right { gap: 0; }
  .hud-btn { min-width: 31px; height: 32px; padding: 0 2px; }
  .hud-btn span { font-size: 15px; }
  .hud-btn[data-menu="friends"], .hud-btn[data-menu="online"] { display: none; }
  .hud-btn[data-menu="team"] { display: flex; }
  .hud-location .eyebrow { font-size: 7px; }
  .world-prompt { bottom: 190px; padding: 7px 12px 7px 7px; }
  .world-prompt span:last-child { font-size: 10.5px; }
  .world-prompt .key { width: 22px; height: 22px; font-size: 10px; }
  .hint-bar { max-width: 92vw; }
  #hint-text { font-size: 9.5px; }
  .dpad { left: 12px; bottom: 78px; width: 116px; height: 116px; }
  .dpad-btn { width: 40px; height: 40px; font-size: 14px; }
  .dpad-btn.up { left: 38px; }
  .dpad-btn.down { left: 38px; }
  .dpad-btn.left { top: 38px; }
  .dpad-btn.right { top: 38px; }
  .touch-actions { right: 12px; bottom: 80px; gap: 8px; }
  .touch-round { width: 54px; height: 54px; font-size: 21px; }
  .touch-round.small { width: 38px; height: 38px; font-size: 14px; }
  .dialog-layer { padding: 0 8px 8px; }
  .dialog-box { padding: 10px; gap: 9px; border-radius: 12px; }
  .dialog-portrait { flex-basis: 68px; width: 68px; height: 68px; }
  .dialog-name { font-size: 15px; }
  .dialog-text { font-size: 12.5px; line-height: 1.45; min-height: 38px; }
  .dialog-hint { display: none; }
  .dialog-choices { gap: 5px; }
  .choice-btn { padding: 7px 9px; }
  .choice-btn span { font-size: 11px; }
  .modal-layer { padding: 8px; }
  .modal { max-height: 94dvh; border-radius: 14px; }
  .modal-head { padding: 11px 13px 8px; }
  .modal-title h2 { font-size: 17px; }
  .modal-icon { font-size: 17px; }
  .modal-body { padding: 11px 12px 14px; }
  .map-canvas { min-height: 300px; padding: 0; }
  .map-side { padding: 11px; }
  .world-map { max-height: 54dvh; }
  .trainer-card { padding: 12px; }
  .tc-main { gap: 9px; }
  .tc-avatar { width: 82px; height: 82px; flex-basis: 82px; }
  .tc-identity h2 { font-size: 22px; }
  .tc-stats { grid-template-columns: repeat(2, 1fr); }
  .tc-footer { flex-direction: column; gap: 3px; }
  .team-list { grid-template-columns: 1fr; }
  .box-grid { grid-template-columns: 1fr 1fr; }
  .item-row, .shop-item { gap: 7px; }
  .item-icon { width: 32px; height: 32px; flex-basis: 32px; font-size: 17px; }
  .friend-card { align-items: flex-start; flex-wrap: wrap; }
  .friend-actions { width: 100%; justify-content: flex-start; padding-left: 68px; }
  .league-info { grid-template-columns: 1fr; }
  .online-rank { flex-wrap: wrap; }
  .rank-record { text-align: left; flex-direction: row; gap: 10px; width: 100%; }
  .ending-stats { grid-template-columns: 1fr 1fr; }
  .battle-top { top: 7px; left: 7px; right: 7px; }
  .battle-log { width: 58vw; max-height: 74px; padding: 6px 7px; }
  .log-line { font-size: 8.5px; }
  .battle-tag { font-size: 7.5px; padding: 4px 7px; }
  .enemy-card { top: 52px; right: 7px; width: 47vw; padding: 6px 7px; }
  .ally-card { bottom: 212px; left: 7px; width: 54vw; padding: 6px 7px; }
  .info-head strong { font-size: 12px; }
  .info-head span { font-size: 8px; }
  .info-card .type-chip { font-size: 7px; padding: 1px 4px; }
  .battle-command { left: 7px; right: 7px; bottom: 7px; width: auto; padding: 7px; gap: 5px; }
  .move-btn { min-height: 38px; padding: 5px 7px; }
  .move-name { font-size: 10px; }
  .move-meta { font-size: 7.5px; }
  .action-btn { padding: 4px 2px; font-size: 12px; }
  .action-btn span { font-size: 8px; }
  .battle-subpanel { left: 7px; right: 7px; bottom: 7px; width: auto; max-height: 72vh; }
  .result-card { padding: 16px; }
  .result-card h2 { font-size: 22px; }
  .splash-names { flex-direction: column; gap: 2px; }
  .title-footer { font-size: 8.5px; }
  .title-tip { display: none; }
}
@media (max-height: 600px) and (orientation: landscape) {
  .intro-art { display: none; }
  .intro-layout { grid-template-columns: 1fr; height: 94dvh; }
  .intro-panel { height: 100%; }
  .intro-text { min-height: 80px; }
  .dpad { bottom: 54px; }
  .touch-actions { bottom: 56px; }
  .world-prompt { bottom: 120px; }
  .ally-card { bottom: 160px; }
  .enemy-card { top: 48px; }
  .battle-log { max-height: 64px; }
}

/* reduced motion */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; }
}

