.trainer-card {
  position: relative; overflow: hidden; border-radius: 18px; padding: 18px;
  background:
    radial-gradient(circle at 80% 10%, rgba(240,201,107,.22), transparent 40%),
    linear-gradient(145deg, #2a3550, #101827 55%, #1d2a44);
  border: 1px solid rgba(240,201,107,.45);
  box-shadow: inset 0 0 40px rgba(0,0,0,.35), 0 20px 40px rgba(0,0,0,.35);
}
.tc-shine { position: absolute; inset: -40%; background: linear-gradient(115deg, transparent 35%, rgba(255,255,255,.12) 48%, transparent 60%); transform: translateX(-30%); animation: shine 5s infinite; pointer-events: none; }
@keyframes shine { 0%,60% { transform: translateX(-45%); } 100% { transform: translateX(45%); } }
.tc-top { display: flex; justify-content: space-between; gap: 10px; font-size: 9px; letter-spacing: 2px; color: var(--gold); border-bottom: 1px solid rgba(240,201,107,.25); padding-bottom: 8px; }
.tc-id { color: var(--muted); letter-spacing: 1px; }
.tc-main { display: flex; gap: 14px; align-items: center; margin: 16px 0 12px; }
.tc-avatar { width: 118px; height: 118px; flex: 0 0 118px; border-radius: 50%; overflow: hidden; border: 2px solid rgba(240,201,107,.5); box-shadow: 0 0 30px rgba(240,201,107,.12); }
.tc-avatar svg { width: 100%; height: 100%; }
.tc-identity h2 { font-family: var(--serif); font-size: 30px; line-height: 1; color: #fff3c4; }
.tc-meta { display: flex; flex-wrap: wrap; gap: 6px 12px; font-size: 11px; color: #c9d3e4; margin: 6px 0; }
.tc-rank { font-size: 11px; color: var(--muted); }
.tc-badges { display: flex; gap: 5px; flex-wrap: wrap; padding: 10px 0; border-top: 1px solid rgba(240,201,107,.18); border-bottom: 1px solid rgba(240,201,107,.18); }
.tc-stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 6px; padding: 12px 0 6px; }
.tc-stats div { display: flex; flex-direction: column; gap: 2px; }
.tc-stats span { font-size: 9px; text-transform: uppercase; letter-spacing: .8px; color: var(--muted); }
.tc-stats strong { font-size: 17px; color: var(--parchment); }
.tc-footer { display: flex; justify-content: space-between; gap: 10px; border-top: 1px solid rgba(240,201,107,.18); padding-top: 9px; margin-top: 6px; font-size: 9.5px; color: var(--muted); }
.card-side h3 { font-family: var(--serif); font-size: 18px; margin-bottom: 8px; }
.card-team { display: grid; gap: 6px; }
.card-mon { display: flex; gap: 8px; align-items: center; padding: 5px; border: 1px solid var(--line-soft); border-radius: 10px; background: rgba(8,13,24,.35); }
.card-mon-art { width: 66px; height: 66px; flex: 0 0 66px; }
.card-mon-info { flex: 1; min-width: 0; }
.card-mon-info strong { display: block; font-size: 12px; }
.card-mon-info span { font-size: 9.5px; color: var(--muted); }
.card-actions { display: grid; gap: 7px; margin-top: 12px; }
.save-note { font-size: 9.5px; color: var(--muted); margin-top: 8px; text-align: center; }
.badge-medal {
  display: inline-flex; align-items: center; justify-content: center; border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, rgba(255,255,255,.35), var(--badge));
  border: 2px solid rgba(255,255,255,.25);
  box-shadow: 0 0 14px color-mix(in srgb, var(--badge) 40%, transparent), inset 0 -3px 8px rgba(0,0,0,.3);
  color: #2b1a08; flex: 0 0 auto;
}
.badge-medal.locked { background: rgba(255,255,255,.06); border-color: rgba(255,255,255,.12); box-shadow: none; color: rgba(255,255,255,.15); filter: grayscale(1); }
.badge-glyph { font-size: 17px; font-weight: 900; text-shadow: 0 1px 0 rgba(255,255,255,.3); }

/* team */
.team-layout { display: grid; grid-template-columns: 330px 1fr; gap: 16px; }
.team-list { display: grid; gap: 7px; align-content: start; }
.team-slot {
  display: flex; align-items: center; gap: 9px; width: 100%; text-align: left;
  padding: 7px; border-radius: 11px; border: 1px solid var(--line-soft);
  background: rgba(8,13,24,.4); color: var(--text); position: relative;
}
.team-slot:hover { border-color: rgba(240,201,107,.4); }
.team-slot.active { border-color: var(--gold); background: rgba(240,201,107,.08); }
.team-slot.fainted { opacity: .55; }
.slot-index { position: absolute; top: 4px; left: 6px; font-size: 8px; color: var(--muted); }
.slot-art { width: 54px; height: 54px; flex: 0 0 54px; display: flex; align-items: center; justify-content: center; }
.slot-main { flex: 1; min-width: 0; }
.slot-main strong { display: block; font-size: 12px; }
.slot-main small { display: block; font-size: 9px; color: var(--muted); margin-bottom: 3px; }
.status-dot { width: 18px; height: 18px; border-radius: 50%; display: inline-flex; align-items: center; justify-content: center; font-size: 8px; font-weight: 800; background: #6b5b95; color: #fff; }
.status-dot.brulure { background: #e4572e; }

