618: export function drawCreature(ctx, species, x, y, scale, opts = {}) {
619:   const mega = !!opts.mega && species.mega
620:   const art = mega ? { ...species.art, ...species.mega.art } : species.art
621:   const t = opts.t || 0
622:   ctx.save()
623:   ctx.translate(x, y)
624:   ctx.scale(scale * (opts.flip ? -1 : 1), scale)
625:   if (opts.alpha != null) ctx.globalAlpha = opts.alpha
626:   // shadow
627:   ctx.save(); ctx.scale(1, .28); ctx.beginPath(); ctx.arc(0, 66, 54, 0, Math.PI * 2)
628:   ctx.fillStyle = 'rgba(8,10,18,.32)'; ctx.fill(); ctx.restore()
629:   drawAura(ctx, art, t, mega)
630:   ctx.translate(0, Math.sin(t * 2.1) * 2)
631:   const kind = art.kind
632:   if (kind === 'beast') drawBeast(ctx, art, t, false)
633:   else if (kind === 'cat') drawBeast(ctx, art, t, true)
634:   else if (kind === 'fish') drawFish(ctx, art, t)
635:   else if (kind === 'plant') drawPlant(ctx, art, t)
636:   else if (kind === 'bird') drawBird(ctx, art, t)
637:   else if (kind === 'bat') drawBat(ctx, art, t)
638:   else if (kind === 'rock') drawRock(ctx, art, t)
639:   else if (kind === 'orb') drawOrb(ctx, art, t)
640:   else if (kind === 'fairy') drawFairy(ctx, art, t)
641:   else if (kind === 'dragon') drawDragon(ctx, art, t, mega)
642:   else if (kind === 'templar') drawTemplar(ctx, art, t, mega)
643:   else if (kind === 'legend') drawLegend(ctx, art, t, species.id)
644:   ctx.restore()
645: }
