647: // Small chibi trainer for the overworld.
648: export function drawTrainer(ctx, x, y, scale, opts = {}) {
649:   const t = opts.t || 0
650:   const walk = opts.walk || 0
651:   const flip = opts.flip ? -1 : 1
652:   const skin = opts.skin || '#e8c39e'
653:   const hair = opts.hair || '#4a2e1a'
654:   const outfit = opts.outfit || '#2f5f9e'
655:   const accent = opts.accent || '#f0c96b'
656:   const hat = opts.hat || 'cap'
657:   ctx.save()
658:   ctx.translate(x, y)
659:   ctx.scale(scale * flip, scale)
660:   ctx.save(); ctx.scale(1, .3); ctx.beginPath(); ctx.arc(0, 24, 18, 0, Math.PI * 2); ctx.fillStyle = 'rgba(8,10,18,.3)'; ctx.fill(); ctx.restore()
661:   const bob = Math.sin(walk * 10) * 1.5
662:   ctx.translate(0, bob)
663:   // legs
664:   const legSwing = Math.sin(walk * 10) * 4
665:   rr(ctx, -8 + legSwing, 8, 7, 16, 3, '#28324a')
666:   rr(ctx, 2 - legSwing, 8, 7, 16, 3, '#28324a')
667:   // body
668:   rr(ctx, -12, -16, 24, 28, 8, outfit, '#1b2438', 2)
669:   rr(ctx, -9, -12, 18, 8, 3, accent)
670:   // arms
671:   rr(ctx, -17, -12, 6, 18, 3, outfit)
672:   rr(ctx, 11, -12, 6, 18, 3, outfit)
673:   // head
674:   ell(ctx, 0, -28, 12, 12, skin, '#7a5a3b', 2)
675:   // hair / hat
676:   if (hat === 'cap') {
677:     ctx.beginPath(); ctx.arc(0, -32, 12, Math.PI, Math.PI * 2); ctx.fillStyle = outfit; ctx.fill()
