  box-shadow: 0 18px 50px rgba(0, 0, 0, .55), inset 0 1px 0 rgba(255, 255, 255, .06);
  transition: opacity .2s ease, transform .2s ease;
}
.tutorial-card.hidden { opacity: 0; transform: translateY(12px); pointer-events: none; }
.tutorial-card::before {
  content: ""; position: absolute; inset: 0; border-radius: inherit; pointer-events: none;
  background: radial-gradient(circle at 8% 0%, rgba(240, 201, 107, .16), transparent 55%);
}
.tut-head { display: flex; align-items: center; gap: 10px; position: relative; }
.tut-icon {
  width: 38px; height: 38px; flex: 0 0 38px; border-radius: 50%;
  display: inline-flex; align-items: center; justify-content: center; font-size: 19px;
  background: rgba(240, 201, 107, .13); border: 1px solid rgba(240, 201, 107, .45); color: var(--gold);
}
.tut-title-wrap { display: grid; gap: 1px; min-width: 0; flex: 1; }
.tut-eyebrow { font-size: 8px; letter-spacing: 1.7px; text-transform: uppercase; color: var(--gold); font-weight: 800; }
.tut-title-wrap strong { font-family: var(--serif); font-size: 14px; color: #fff3c4; line-height: 1.15; }
.tut-close {
  width: 26px; height: 26px; flex: 0 0 26px; border-radius: 50%; border: 1px solid rgba(240, 201, 107, .25);
  background: rgba(0, 0, 0, .2); color: #9aa7bd; font-size: 12px; line-height: 1;
}
.tut-close:hover { color: #fff; border-color: rgba(240, 201, 107, .6); }
.tutorial-card p { position: relative; margin: 8px 0 9px; font-size: 11.5px; line-height: 1.45; color: #d6deeb; }
.tut-foot { position: relative; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
.tut-dots { display: flex; gap: 4px; flex: 1; }
.tut-dot { width: 6px; height: 6px; border-radius: 50%; background: rgba(154, 167, 189, .35); }
.tut-dot.done { background: var(--gold2); }
.tut-dot.active { background: var(--gold); box-shadow: 0 0 8px rgba(240, 201, 107, .8); }
.tut-key {
  font-size: 8px; font-weight: 800; letter-spacing: 1px; text-transform: uppercase;
  color: #ffd98a; background: rgba(0, 0, 0, .3); border: 1px solid rgba(240, 201, 107, .22);
  padding: 3px 6px; border-radius: 20px; white-space: nowrap;
}
.tut-next {
  border: 1px solid rgba(240, 201, 107, .5); background: rgba(240, 201, 107, .14);
  color: #ffe8a8; border-radius: 20px; padding: 4px 9px; font-size: 9.5px; font-weight: 800;
}
.tut-next:hover { background: rgba(240, 201, 107, .24); }

/* generation chip in battle + dex */
.gen-chip {
  display: inline-flex; align-items: center; gap: 3px; font-size: 7.5px; font-weight: 800;
  letter-spacing: .8px; text-transform: uppercase; color: #9ff3ec;
  border: 1px solid rgba(125, 224, 216, .4); background: rgba(125, 224, 216, .1);
  border-radius: 20px; padding: 1px 5px; margin-left: 4px; vertical-align: middle;
}
.visitor-tag {
  border-color: rgba(125, 224, 216, .5) !important; color: #9ff3ec !important;
  background: rgba(125, 224, 216, .1) !important;
}

/* Pokédex */
.dex-modal .modal-body { padding: 12px 14px 16px; }
.dex-toolbar { display: flex; align-items: center; justify-content: space-between; gap: 10px; flex-wrap: wrap; margin-bottom: 9px; }
.dex-tabs { display: flex; gap: 5px; overflow-x: auto; padding-bottom: 2px; }
.dex-tab {
  border: 1px solid var(--line-soft); background: rgba(8, 13, 24, .4); color: #c9d3e4;
  border-radius: 20px; padding: 4px 9px; font-size: 9px; font-weight: 700; white-space: nowrap;
}
.dex-tab.active { border-color: rgba(240, 201, 107, .65); background: rgba(240, 201, 107, .14); color: #ffe8a8; }
.dex-count { font-size: 9.5px; color: var(--muted); white-space: nowrap; }
.dex-count b { color: var(--gold); }
.dex-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(142px, 1fr)); gap: 7px; max-height: 56dvh; overflow-y: auto; padding: 2px; }
.dex-card {
  position: relative; display: grid; grid-template-columns: 54px 1fr; gap: 7px; align-items: center;
  padding: 7px; border-radius: 11px; border: 1px solid var(--line-soft);
  background: linear-gradient(150deg, rgba(20, 31, 54, .65), rgba(8, 13, 24, .45));
}
.dex-card.seen { border-color: rgba(240, 201, 107, .28); }
.dex-card.caught { border-color: rgba(125, 224, 216, .45); background: linear-gradient(150deg, rgba(125, 224, 216, .09), rgba(8, 13, 24, .45)); }
.dex-art { width: 54px; height: 54px; display: flex; align-items: center; justify-content: center; }
.dex-art canvas { width: 54px !important; height: 54px !important; }
.dex-card.unseen .dex-art { filter: grayscale(1) brightness(.45); opacity: .7; }
.dex-info { min-width: 0; }
.dex-info strong { display: block; font-size: 11px; color: var(--parchment); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.dex-card.unseen .dex-info strong { color: #7d8799; }
.dex-info small { display: block; font-size: 8px; color: var(--muted); letter-spacing: .4px; }
.dex-info .type-row { margin-top: 2px; gap: 2px; }
.dex-info .type-chip { font-size: 6.5px; padding: 1px 4px; }
.dex-status { position: absolute; top: 4px; right: 5px; font-size: 8px; opacity: .8; }
.dex-note { margin-top: 9px; border-left: 2px solid var(--teal); padding: 7px 0 7px 10px; font-size: 10.5px; line-height: 1.45; color: #d6deeb; }
.dex-note strong { color: #9ff3ec; }

/* online alpha */
.alpha-banner {
  display: flex; align-items: center; gap: 10px; padding: 10px 12px; margin-bottom: 10px;
  border-radius: 12px; border: 1px solid rgba(125, 224, 216, .35);
  background: linear-gradient(100deg, rgba(125, 224, 216, .13), rgba(11, 17, 32, .55));
}
.alpha-banner .ab-icon {
  width: 36px; height: 36px; flex: 0 0 36px; border-radius: 50%; display: inline-flex; align-items: center; justify-content: center;
  font-size: 18px; background: rgba(125, 224, 216, .13); border: 1px solid rgba(125, 224, 216, .45);
}
.alpha-banner strong { display: block; font-size: 12px; color: #d8fffb; }
.alpha-banner small { display: block; font-size: 9.5px; color: #a9c6d8; line-height: 1.35; }
.alpha-badge {
  font-size: 8px; font-weight: 800; letter-spacing: 1.2px; text-transform: uppercase;
  color: #0b1120; background: linear-gradient(100deg, #9ff3ec, #f0c96b);
  padding: 2px 7px; border-radius: 20px; white-space: nowrap;
}
.online-locked {
  text-align: center; padding: 22px 16px; border-radius: 13px;
  border: 1px dashed rgba(240, 201, 107, .35); background: rgba(8, 13, 24, .35);
}
.online-locked .lock-orb { font-size: 38px; margin-bottom: 7px; }
.online-locked h3 { font-family: var(--serif); font-size: 20px; color: #fff3c4; }
.online-locked p { max-width: 440px; margin: 7px auto 0; font-size: 11.5px; line-height: 1.55; color: #c9d3e4; }
.online-badge-req {
  display: inline-flex; align-items: center; gap: 6px; margin-top: 11px; padding: 5px 10px;
  border-radius: 20px; border: 1px solid rgba(240, 201, 107, .35); background: rgba(240, 201, 107, .08);
  font-size: 9.5px; font-weight: 700; color: var(--gold);
}
.online-badge-req .req-dot { width: 7px; height: 7px; border-radius: 50%; background: #e4572e; box-shadow: 0 0 8px #e4572e; }
.online-badge-req .req-dot.ok { background: #7de0d8; box-shadow: 0 0 8px #7de0d8; }

@media (max-width: 640px) {
  .title-news { font-size: 9px; padding: 6px 9px; }
  .tutorial-card { left: 8px; right: 8px; bottom: 148px; width: auto; padding: 9px 10px; }
  .tut-icon { width: 32px; height: 32px; flex-basis: 32px; font-size: 16px; }
  .tut-title-wrap strong { font-size: 12px; }
  .tutorial-card p { font-size: 10.5px; margin: 6px 0 7px; }
  .tut-key { display: none; }
  .tut-next { font-size: 8.5px; padding: 3px 7px; }
  .dex-grid { grid-template-columns: repeat(auto-fill, minmax(130px, 1fr)); max-height: 52dvh; }
  .dex-card { grid-template-columns: 46px 1fr; }
  .dex-art, .dex-art canvas { width: 46px !important; height: 46px !important; }
}
@media (max-height: 600px) and (orientation: landscape) {
  .tutorial-card { bottom: 8px; left: 8px; width: min(310px, 42vw); }
  .tutorial-card p { display: none; }
}
